// Real-World Money Survival practice variants + worked examples (2026-10-04).
import { ADULT_PRACTICE_VARIANT_BANK } from './adult-life.js';

const RWMS_PRACTICE = {"nd-money":[{"verb":"decide","basis":"street","prompt":"Liam has autism and loves routine. He keeps blowing his budget on food delivery apps because his card is saved in every one. What is the BEST first move?","choices":[{"id":"a","label":"Delete the saved card numbers and set a 24-hour rule for unplanned orders","feedback":"[Street-smart] Removing the saved card adds friction between impulse and purchase, and the 24-hour rule gives the impulse time to fade."},{"id":"b","label":"Set a daily alarm labeled \"don't order food\"","feedback":"[Street-smart] An alarm is a reminder to rely on willpower — it does not change the setup. Friction beats reminders."},{"id":"c","label":"Only order from the one app he likes most","feedback":"[Street-smart] Fewer apps does not fix the core problem: one-tap ordering with a saved card. The friction has to go in."},{"id":"d","label":"Eat out more so delivery feels expensive by comparison","feedback":"[Street-smart] That just adds a second spending leak. Compare the real fix: remove the easy button."}],"correct":"a"},{"verb":"spot","basis":"street","prompt":"Maya gets $20 a week for groceries. She taps to pay and the money \"doesn't feel real\" until it is gone. Which setup makes the spending visible for her?","choices":[{"id":"a","label":"A cash envelope for groceries — physical bills she can see and count","feedback":"[Street-smart] Physical cash is impossible to ignore: when the envelope is thin, the brain registers it immediately."},{"id":"b","label":"A credit card with a high limit for grocery emergencies","feedback":"[Street-smart] A high limit does the opposite — it hides the damage and adds debt on top. Visibility is the goal."},{"id":"c","label":"Memorizing her PIN so checkout is faster","feedback":"[Street-smart] Faster checkout is the enemy here. Speed is what makes spending invisible."},{"id":"d","label":"Buying everything on Monday so she does not think about it all week","feedback":"[Street-smart] Bulk-buying without a system just moves the invisible spending to one day. Track it, don't batch it."}],"correct":"a"},{"verb":"compare","basis":"street","prompt":"Two ADHD-friendly budgeting ideas: (1) a whiteboard with a running weekly total on the fridge, (2) a detailed spreadsheet reviewed monthly. Which works better and why?","choices":[{"id":"a","label":"The whiteboard — it is visible daily and updates take seconds","feedback":"[Street-smart] Visible, fast, always-there. A spreadsheet you open monthly fails the \"shows up on its own\" test."},{"id":"b","label":"The spreadsheet — more detail is always better","feedback":"[Street-smart] More detail means more friction. Systems that need effort die fast for ADHD brains."},{"id":"c","label":"Both equally, as long as he means it","feedback":"[Street-smart] Intention does not matter; the design does. One of these designs is clearly stronger."},{"id":"d","label":"Neither — budgeting is impossible with ADHD","feedback":"[Street-smart] Not true. Thousands of people with ADHD budget well — with systems built for their brains, not against them."}],"correct":"a"},{"verb":"predict","basis":"street","prompt":"A teen with ADHD spends $300 a month on mobile games with in-app purchases enabled. He turns them OFF in phone settings (Screen Time / purchase controls). What happens next?","choices":[{"id":"a","label":"Impulse purchases drop because the easy button is gone","feedback":"[Street-smart] Removing in-app purchases kills the one-tap impulse path. Most of that spending was impulse, not planned."},{"id":"b","label":"He spends the same amount on games another way","feedback":"[Street-smart] Possible but unlikely to match it — the friction of finding workarounds filters out most impulse buys."},{"id":"c","label":"He deletes all his games immediately","feedback":"[Street-smart] Unlikely — the setting blocks purchases, not play. He can still enjoy the games for free."},{"id":"d","label":"Nothing changes — settings do not affect behavior","feedback":"[Street-smart] Settings are exactly what changes behavior. Environment design is the whole strategy here."}],"correct":"a"},{"verb":"explain","basis":"street","prompt":"Why do money experts tell neurodivergent teens to attach budget check-ins to existing routines (\"every Sunday after breakfast\") instead of just scheduling them?","choices":[{"id":"a","label":"Routines you already do need no motivation — the check-in rides along for free","feedback":"[Street-smart] Existing habits are automatic. Bolting the check-in onto one removes the \"remember to do it\" step that fails."},{"id":"b","label":"Sunday breakfast has special financial meaning","feedback":"[Street-smart] No — the meal is arbitrary. Any existing routine works. It is the attachment that matters, not the activity."},{"id":"c","label":"Five minutes is too short to matter","feedback":"[Street-smart] Five honest minutes weekly beats a monthly hour you keep skipping. Small and consistent wins."},{"id":"d","label":"Because parents can supervise breakfast","feedback":"[Street-smart] This is about self-reliance, not supervision. The system should work when nobody is watching."}],"correct":"a"},{"verb":"mc","basis":"street","prompt":"Which marketing-trap removal gives an impulsive shopper the biggest win?","choices":[{"id":"a","label":"Unsubscribe from all marketing emails + remove saved cards from shopping sites","feedback":"[Street-smart] This attacks both triggers at once: no more sale-bait in the inbox, and checkout takes effort instead of one click."},{"id":"b","label":"Keep the emails but promise not to click them","feedback":"[Street-smart] Willpower against engineered temptation is a losing fight. Remove the trigger."},{"id":"c","label":"Move marketing emails to a folder and check them weekly","feedback":"[Street-smart] A sale folder is still a sale folder. Unsubscribe removes the temptation entirely."},{"id":"d","label":"Use a different email address for shopping sites","feedback":"[Street-smart] A second inbox still gets the same bait. Unsubscribing is the real fix."}],"correct":"a"},{"verb":"decide","basis":"street","prompt":"Jordan autistically hates surprises. Autopay hits his account at random-feeling times and overdrafts it. What system respects his need for predictability?","choices":[{"id":"a","label":"List every autopay with its date on a wall calendar and keep a buffer in checking","feedback":"[Street-smart] A visible calendar turns surprises into a schedule, and a buffer absorbs timing wobbles. Predictability restored."},{"id":"b","label":"Turn off all autopay and hope he remembers","feedback":"[Street-smart] Replacing autopay with memory is worse — memory is the unreliable part. Keep the automation, make it visible."},{"id":"c","label":"Pay everything early with a credit card","feedback":"[Street-smart] That just moves the surprise to the card bill and adds interest risk. Visibility first."},{"id":"d","label":"Close his checking account and use cash only","feedback":"[Street-smart] Extreme and impractical — bills are digital now. Calm the system, don't abandon it."}],"correct":"a"},{"verb":"spot","basis":"street","prompt":"Which tracking tool is BEST for a brain that forgets what it cannot see?","choices":[{"id":"a","label":"A \"spent this week\" jar where every receipt goes the moment money leaves","feedback":"[Street-smart] Physical, immediate, visual. The jar fills up and the brain sees the spending happen."},{"id":"b","label":"A budgeting app that only syncs when opened","feedback":"[Street-smart] An app that hides until opened is invisible money again. The tool has to show up on its own."},{"id":"c","label":"Mental math at the end of each day","feedback":"[Street-smart] Mental tracking is exactly what fails for object-permanence struggles. Externalize it."},{"id":"d","label":"A yearly budget printed once in January","feedback":"[Street-smart] A yearly sheet is invisible 364 days a year. Tracking has to be daily-visible."}],"correct":"a"},{"verb":"decide","basis":"street","prompt":"Jordan wants Maya's results. He has ADHD, hates paperwork, and shops on his phone constantly. What is his best first step?","choices":[{"id":"t0c0","label":"Delete saved card numbers from his shopping apps and turn on transaction notifications","feedback":"[Street-smart] Exactly — delete the one-tap path and make every dollar visible. Friction and visibility, not willpower. [Street-smart] Environment beats willpower: fewer impulse triggers (no saved cards) plus visibility (notifications) is the highest-leverage first step."},{"id":"t0c1","label":"Build a detailed monthly budget in a spreadsheet","feedback":"[Street-smart] Not quite — Maya's system worked because it removed triggers and made money visible, not because she added paperwork or promises."},{"id":"t0c2","label":"Promise himself to think before every purchase","feedback":"[Street-smart] Not quite — Maya's system worked because it removed triggers and made money visible, not because she added paperwork or promises."},{"id":"t0c3","label":"Switch to a bank with a nicer app","feedback":"[Street-smart] Not quite — Maya's system worked because it removed triggers and made money visible, not because she added paperwork or promises."}],"correct":"t0c0"},{"verb":"predict","basis":"street","prompt":"Liam disables in-app purchases in his phone settings and puts a \"spent this week\" jar on his desk. What happens to his game spending?","choices":[{"id":"t1c0","label":"It drops — the impulse path is blocked and the jar makes spending visible","feedback":"[Street-smart] Right — blocking the one-tap path kills most impulse buys, and the jar gives his brain the visible signal it was missing. [Street-smart] Two systems, two jobs: purchase controls remove the trigger, the jar replaces invisible taps with a signal the brain registers."},{"id":"t1c1","label":"It stays the same — settings cannot change habits","feedback":"[Street-smart] Not quite — the spending was driven by an invisible, frictionless path. Block the path and make it visible, and the spending falls."},{"id":"t1c2","label":"He stops playing games entirely","feedback":"[Street-smart] Not quite — the spending was driven by an invisible, frictionless path. Block the path and make it visible, and the spending falls."},{"id":"t1c3","label":"The jar fills with money he saved","feedback":"[Street-smart] Not quite — the spending was driven by an invisible, frictionless path. Block the path and make it visible, and the spending falls."}],"correct":"t1c0"}],"banking":[{"verb":"decide","basis":"street","prompt":"A bank charges a $12 monthly fee when savings drops below $300. Maya has $310 in savings. What should she watch out for?","choices":[{"id":"check-obligations","label":"One $20 purchase could drop her below $300 and trigger the fee, pushing her even lower","feedback":"[Street-smart] This is the fee trap: the fee itself drags the balance down, which can trigger more fees. Read the fee schedule before opening any account."},{"id":"spend-visible","label":"She is safe because she is above $300 today","feedback":"[Street-smart] Barely-above is barely-safe. One small withdrawal crosses the line."},{"id":"assume-overdraft","label":"Fees only apply to checking accounts","feedback":"[Street-smart] No — savings accounts carry minimum-balance fees too. Always read the fee schedule."},{"id":"split-purchase","label":"The bank will warn her before charging","feedback":"[Street-smart] Banks are not required to warn you first. The fee schedule is the warning — read it."}],"correct":"check-obligations"},{"verb":"compare","basis":"research","prompt":"National averages mid-2026: money market accounts ~0.65%, regular savings ~0.38%, with the best accounts near ~4%. Jordan has $3,000 and wants slightly higher rates plus check-writing access. Which account type fits?","choices":[{"id":"check-obligations","label":"A money market account — check-writing/debit access, slightly higher rates, both FDIC-insured to $250k","feedback":"[Research-backed] MMAs offer check-writing and slightly higher average rates than regular savings, and both are FDIC-insured to $250,000."},{"id":"spend-visible","label":"A regular savings account — it always pays more than an MMA","feedback":"[Research-backed] Not true on average: MMAs averaged ~0.65% vs ~0.38% for savings mid-2026. High-yield savings can compete, but plain savings usually pays less."},{"id":"assume-overdraft","label":"An MMA — because it is not FDIC insured","feedback":"[Research-backed] Wrong: MMAs at banks are FDIC-insured to $250k, same as savings. (Do not confuse with money market mutual funds.)"},{"id":"split-purchase","label":"Whichever account has the flashiest app","feedback":"[Research-backed] The app does not determine your rate or fees. Compare rates and minimums, not design."}],"correct":"check-obligations"},{"verb":"spot","basis":"street","prompt":"Liam reads his bank's fee schedule before opening an account. What is he MOST likely to find?","choices":[{"id":"check-obligations","label":"Minimum-balance fees, monthly service fees, and overdraft fees spelled out","feedback":"[Street-smart] The fee schedule lists the real cost of the account. Reading it before signing is the whole move."},{"id":"spend-visible","label":"A guarantee of zero fees forever","feedback":"[Street-smart] No bank guarantees that. Fee schedules change — and \"free\" usually has conditions."},{"id":"assume-overdraft","label":"Only the interest rate, nothing else","feedback":"[Street-smart] The rate is the advertisement; the fees are the fine print. Both live in the paperwork."},{"id":"split-purchase","label":"Fees written in invisible ink","feedback":"[Street-smart] They are not hidden — they are just in the fine print most people skip. Read it."}],"correct":"check-obligations"},{"verb":"predict","basis":"street","prompt":"Maya reuses the same password everywhere and gets a text: \"Your bank sent a code: 482913. Reply to verify.\" What is the safe response?","choices":[{"id":"check-obligations","label":"Delete it — never share login codes, and switch to a password manager plus 2FA","feedback":"[Street-smart] Banks never ask for codes by text. Never share login codes, use a password manager instead of reused passwords, and turn on two-factor."},{"id":"spend-visible","label":"Reply with the code to be safe","feedback":"[Street-smart] That is exactly how accounts get stolen. Real banks never ask for codes this way."},{"id":"assume-overdraft","label":"Click the link in the text to check her account","feedback":"[Street-smart] Phishing links look like bank sites but steal logins. Go to the bank app or site directly."},{"id":"split-purchase","label":"Forward the code to a friend to check if it is real","feedback":"[Street-smart] Sharing codes with anyone — even a friend — breaks security. Codes stay private."}],"correct":"check-obligations"},{"verb":"explain","basis":"street","prompt":"Why can Liam's banking app show $120 \"available\" when his statement shows $200 \"posted\"?","choices":[{"id":"check-obligations","label":"Pending holds (like a gas station or hotel) reserve money before the final charge posts","feedback":"[Street-smart] Available balance subtracts pending holds; posted balance does not — until the charge settles. Spend from the available number."},{"id":"spend-visible","label":"The bank is stealing $80","feedback":"[Street-smart] No — holds are temporary reservations, not theft. The difference settles when charges finalize."},{"id":"assume-overdraft","label":"Available balance is just an estimate the bank guesses","feedback":"[Street-smart] It is not a guess — it is your real balance minus money already committed. Trust it over the posted number."},{"id":"split-purchase","label":"Posted balance is always the number to spend from","feedback":"[Street-smart] Spending from posted while holds exist is how overdrafts happen. Available is the safe number."}],"correct":"check-obligations"},{"verb":"mc","basis":"research","prompt":"A high-yield savings account advertises ~4% with a $0 minimum. An MMA advertises ~0.65% with a $2,500 minimum to open. For someone starting with $300, which is the better fit?","choices":[{"id":"check-obligations","label":"The high-yield savings — low minimum, competitive rate, FDIC-insured to $250k","feedback":"[Research-backed] HYSA accounts often compete with MMA rates while keeping minimums low — both are FDIC-insured to $250,000."},{"id":"spend-visible","label":"The MMA — higher minimums always mean higher rates","feedback":"[Research-backed] Not always: this MMA's average rate (~0.65%) is well below the ~4% HYSA. Compare actual numbers, not assumptions."},{"id":"assume-overdraft","label":"Neither — rates this high cannot be FDIC insured","feedback":"[Research-backed] Rate level does not determine insurance. Both account types at banks are FDIC-insured to $250k."},{"id":"split-purchase","label":"The MMA — he cannot even open it yet, so save up for it","feedback":"[Research-backed] Waiting to qualify for a lower-rate account makes no sense. The HYSA is open to him now and pays more."}],"correct":"check-obligations"},{"verb":"decide","basis":"street","prompt":"Jordan signs up for a new bank app. What is the single best security move during setup?","choices":[{"id":"check-obligations","label":"Turn on two-factor authentication and store the password in a password manager","feedback":"[Street-smart] 2FA blocks most account takeovers, and a password manager kills password reuse. Do both at setup."},{"id":"spend-visible","label":"Use his birthday as the password so he remembers it","feedback":"[Street-smart] Memorable passwords are guessable passwords. Let a password manager remember a random one."},{"id":"assume-overdraft","label":"Skip 2FA because it is annoying","feedback":"[Street-smart] 2FA takes ten seconds and stops the most common attacks. \"Annoying\" is cheap insurance."},{"id":"split-purchase","label":"Write the password on a sticky note on his monitor","feedback":"[Street-smart] Anyone near the desk now has the keys. A password manager is the sticky note that cannot be read."}],"correct":"check-obligations"},{"verb":"compare","basis":"street","prompt":"Two savings accounts: Bank A charges a monthly fee under a $300 minimum; Bank B has no minimum but charges $35 overdraft fees. A teen who sometimes dips low should pick which — and why?","choices":[{"id":"check-obligations","label":"Depends on his habits — read both fee schedules and pick the fees he is least likely to trigger","feedback":"[Street-smart] There is no universally best account — the best account is the one whose fees YOU will not trigger. Read the schedule, match it to your habits."},{"id":"spend-visible","label":"Always Bank A — monthly fees are cheaper","feedback":"[Street-smart] Not necessarily: a $12 monthly fee is $144 a year — worse than one overdraft. Do the math on your own behavior."},{"id":"assume-overdraft","label":"Always Bank B — no minimum means no fees ever","feedback":"[Street-smart] Bank B still has overdraft fees. \"No minimum\" is not \"no fees.\" Read the whole schedule."},{"id":"split-purchase","label":"Pick whichever is closer to his house","feedback":"[Street-smart] Branch distance does not determine fees. The fee schedule does."}],"correct":"check-obligations"}],"credit":[{"verb":"decide","basis":"research","prompt":"Jordan wants to raise his credit score over the next year. Four habits are on the table. Which one moves the needle most?","choices":[{"id":"borrowed","label":"Pay every bill on time, every month — no exceptions.","feedback":"[Research-backed] Right. Payment history is 35% of a FICO score, the single biggest slice. Nothing else you do matters as much as on-time payments."},{"id":"income","label":"Open three new cards to improve his credit mix.","feedback":"[Research-backed] Credit mix is only 10%, and new applications can ding the score short-term. Mix is garnish; payment history is the meal."},{"id":"savings","label":"Apply for a new card every few months to show lenders he is active.","feedback":"[Research-backed] New credit is only 10% of the score, and each application can cost a few points. Frequent applications signal risk, not reliability."},{"id":"free-until-bill","label":"Carry a small balance each month so the bank sees usage.","feedback":"[Research-backed] Carrying a balance builds zero extra score — on-time payments and low utilization do the work. The balance just adds interest you did not need to pay."}],"correct":"borrowed"},{"verb":"spot","basis":"research","prompt":"Maya reads that credit utilization should stay under 30%. This month hers lands at 31%. What is the honest read?","choices":[{"id":"borrowed","label":"Nothing dramatic — 30% is guidance, not a cliff; lower is generally better, but one point over does not flip a switch.","feedback":"[Research-backed] Right. Under 30% is a rule of thumb from Experian and FICO guidance, not a magic line. 31% is not a penalty tier; the trend matters more than the exact number."},{"id":"income","label":"Her score drops a full tier the moment she crosses 30%.","feedback":"[Research-backed] There is no cliff at 30%. Scores move on gradients — 31% vs 29% is a nudge, not a punishment."},{"id":"savings","label":"She must pay it below 30% today or the whole month is ruined.","feedback":"[Research-backed] Utilization has no memory month to month in most scoring models — next month’s lower number simply replaces this one. Panic-paying today buys nothing."},{"id":"free-until-bill","label":"Utilization does not matter at all, so she can ignore it.","feedback":"[Research-backed] It is 30% of the score — the second-biggest factor. It matters; it is just not a cliff."}],"correct":"borrowed"},{"verb":"compare","basis":"research","prompt":"Liam hears two claims: “You must carry a balance to build credit” versus “Pay the card in full every month.” Which is true, and why?","choices":[{"id":"borrowed","label":"Pay in full. On-time payments and low utilization build the score — carrying a balance adds interest, not points.","feedback":"[Research-backed] Right. The score sees that you paid on time and how much you owe. It does not give bonus points for paying interest. Paying in full builds the same history for free."},{"id":"income","label":"Carry a balance — lenders reward borrowers who pay them interest.","feedback":"[Research-backed] Lenders like profit, but the scoring formula does not reward you for paying interest. A carried balance only raises your utilization, which can hurt."},{"id":"savings","label":"Both work the same, so carry whatever feels easier.","feedback":"[Research-backed] They are not the same: carrying costs you interest every month while building nothing extra. Paying in full is strictly better."},{"id":"free-until-bill","label":"Pay in full, but skip a month sometimes to keep the account “active.”","feedback":"[Research-backed] Skipping a month is a missed payment — the single most damaging thing for the 35% payment-history slice. Activity means using the card, not skipping payments."}],"correct":"borrowed"},{"verb":"predict","basis":"research","prompt":"A card offers 3% cashback. Maya spends $100 she was already going to spend. Predict the outcome — and the lesson.","choices":[{"id":"borrowed","label":"She gets $3 back. The reward is tiny next to the $100 that earned it — never spend extra to chase cashback.","feedback":"[Research-backed] Right. 3% of $100 is $3, by plain arithmetic. Cashback is a small rebate on spending you were doing anyway — the moment you spend extra to “earn” it, you lose."},{"id":"income","label":"She basically made $3 of free profit.","feedback":"[Research-backed] She spent $100 to get $3. That is not profit — it is a 3% discount on money already leaving. Profit would be keeping the $100."},{"id":"savings","label":"She should spend another $50 to earn even more back.","feedback":"[Research-backed] $50 more spending earns $1.50 and costs $48.50 net. Chasing rewards with extra spending is how a 3% rebate becomes a 100% loss."},{"id":"free-until-bill","label":"The $3 wipes out any interest if she carries the balance.","feedback":"[Research-backed] One month of interest on a $100 balance at 24% is about $2 — and it compounds monthly. Rewards never outrun carried interest. Pay in full or the math eats you."}],"correct":"borrowed"},{"verb":"explain","basis":"street","prompt":"Explain the trap in “Spend $1,000 in 3 months, get a $250 bonus!”","choices":[{"id":"borrowed","label":"The $250 costs $1,000 of spending you might not have done — and if any of it carries interest at ~20%, the bonus evaporates fast.","feedback":"[Street-smart] Right. Bonuses are priced into the card’s business model: they bet you will spend extra and carry some of it. Only chase a bonus on spending that was happening anyway, paid in full."},{"id":"income","label":"There is no trap — $250 is free money.","feedback":"[Street-smart] Nothing with a spending requirement is free. The requirement is the price; the question is whether you were already going to pay it."},{"id":"savings","label":"The trap is the paperwork, not the spending.","feedback":"[Street-smart] Paperwork is annoying, but the money trap is the $1,000 of incentivized spending and the interest if it is not paid in full."},{"id":"free-until-bill","label":"The $250 gets taxed away completely, so it is worthless.","feedback":"[Street-smart] Credit card rewards are generally not taxed as income in the US. The real cost is the spending requirement, not taxes."}],"correct":"borrowed"},{"verb":"mc","basis":"street","prompt":"Which card term should make you walk away?","choices":[{"id":"income","label":"0% for 12 months, then 24% on whatever balance is left — clearly stated up front.","feedback":"[Street-smart] This one is at least honest: you know the promo ends and exactly what hits the remainder. Dangerous only if you ignore the deadline — but the terms are visible."},{"id":"savings","label":"2% cashback with a $95 annual fee you forgot to check.","feedback":"[Street-smart] A $95 fee needs $4,750 of spending just to break even on 2% back. Fees are a cost like any other — but they are not the silent killer here."},{"id":"borrowed","label":"0% for 12 months, then interest charged RETROACTIVELY on the original purchase amount if any balance remains (deferred interest).","feedback":"[Street-smart] Right — this is the killer. Leave $50 unpaid on a $1,200 purchase and you can owe a year of interest on the full $1,200, not the $50. Read the terms; “deferred interest” means the 0% was never real."},{"id":"free-until-bill","label":"No rewards, 15% APR, and you pay in full monthly.","feedback":"[Street-smart] Boring and safe. No rewards is not a trap — carrying a balance under deferred interest is."}],"correct":"borrowed"},{"verb":"decide","basis":"street","prompt":"Liam’s brain does not flag tapping his phone to pay as “spending” — the money never feels gone. Which system helps him most?","choices":[{"id":"borrowed","label":"Set a daily spend limit in his bank app, so the limit does the noticing when his brain doesn’t.","feedback":"[Street-smart] Right. When money doesn’t feel spent, willpower has nothing to grip — a hard limit in the app is an external system that stops the slide before it starts. Build the environment, don’t fight the brain."},{"id":"income","label":"Just try harder to remember every purchase.","feedback":"[Street-smart] Memory is exactly what’s unreliable here. A system beats a resolution every time — especially for brains where out-of-sight means out-of-mind."},{"id":"savings","label":"Check the balance once a month and adjust next month.","feedback":"[Street-smart] A monthly glance finds the damage after it is done. Daily limits prevent it; monthly reviews just document it."},{"id":"free-until-bill","label":"Stop using cards entirely — limits are for other people.","feedback":"[Street-smart] All-or-nothing usually collapses, and it teaches nothing. A limit keeps the tool usable while removing the trap."}],"correct":"borrowed"},{"verb":"spot","basis":"street","prompt":"Spot the TRUE statement about credit cards.","choices":[{"id":"borrowed","label":"They are a trap that can be a tool — ONLY if you pay the balance in full every month. The day you carry a balance, the trap snaps shut.","feedback":"[Street-smart] Right. Paid in full monthly: free short-term loan, fraud protection, history-building. Carried balance: ~20%+ interest working against you from day one. The line between tool and trap is exactly one missed full payment."},{"id":"income","label":"They are free money as long as you stay under the credit limit.","feedback":"[Street-smart] The limit is how much the bank trusts you, not how much you can afford. Every dollar spent is a dollar owed — the limit is not a budget."},{"id":"savings","label":"Paying the minimum keeps you safe from all fees and damage.","feedback":"[Street-smart] Minimums avoid late fees but the balance keeps compounding at ~20%+. “Safe from fees” while the debt quietly doubles is not safe."},{"id":"free-until-bill","label":"Interest only matters on big purchases.","feedback":"[Street-smart] Interest is a percentage — it bites small balances too, and small carried balances have a habit of becoming big ones."}],"correct":"borrowed"}],"debt-warfare":[{"verb":"decide","basis":"research","prompt":"Maya owes: a $400 store card (min $25), a $2,500 card (min $60), and a $6,000 loan (min $130). She has an extra $200/month. Decide the snowball move.","choices":[{"id":"a","label":"Minimums on all three; all $200 extra at the $400 store card until it is gone, then roll that payment into the next.","feedback":"[Research-backed] Right. List smallest to largest, minimums on everything so nothing slips, every spare dollar at the smallest. When it dies, its whole payment joins the attack on the next one."},{"id":"b","label":"Split the $200 evenly across all three debts.","feedback":"[Research-backed] Even splits feel fair but delay the first payoff — and the first payoff is the psychological fuel the whole method runs on."},{"id":"c","label":"All $200 at the $6,000 loan — biggest debt first.","feedback":"[Research-backed] Attacking the biggest first means months with zero debts killed and zero wins. Snowball orders by balance, smallest first, on purpose."},{"id":"d","label":"Skip minimums on the big debts to kill the small one faster.","feedback":"[Research-backed] Skipping minimums triggers late fees and credit damage. The snowball is built on top of minimums, never instead of them."}],"correct":"a"},{"verb":"spot","basis":"research","prompt":"Spot the HONEST statement about snowball vs. avalanche.","choices":[{"id":"a","label":"Avalanche (highest interest first) saves more money mathematically; snowball (smallest first) wins on follow-through, because early wins keep people going.","feedback":"[Research-backed] Right — this is the real tradeoff, and the CFPB says the same: the snowball’s quick progress is a great motivator, while the highest-rate method can save money long-term. Honest advice names both and lets you pick the one you will finish."},{"id":"b","label":"Snowball always saves the most money.","feedback":"[Research-backed] No — ignoring interest rates can cost more in interest. Snowball’s edge is behavioral (you stick with it), not mathematical."},{"id":"c","label":"Avalanche only works if you have exactly one debt.","feedback":"[Research-backed] Avalanche is a multi-debt strategy: order every debt by interest rate, highest first. It works with any number of debts."},{"id":"d","label":"The method does not matter as long as you pay something.","feedback":"[Research-backed] Paying only minimums with no plan is how a $2,000 balance survives for decades. The method is the plan — it decides where extra dollars go."}],"correct":"a"},{"verb":"compare","basis":"research","prompt":"Compare two offers on a $15,000 car at 8%: 36 months at ~$470/mo vs 60 months at ~$304/mo. (Example numbers, rounded.)","choices":[{"id":"a","label":"The 60-month loan feels cheaper monthly but costs about $1,350 MORE in total interest (~$3,250 vs ~$1,900) — longer term, lower payment, more interest.","feedback":"[Research-backed] Right. Interest accrues on the remaining balance every month, so stretching the payoff keeps a bigger balance alive longer. The dealer sells the low payment; the price is the extra interest."},{"id":"b","label":"The 60-month loan is cheaper overall because the monthly payment is lower.","feedback":"[Research-backed] Lower payment is not lower cost. 60 payments of ~$304 total ~$18,250; 36 payments of ~$470 total ~$16,900. Same car, ~$1,350 apart."},{"id":"c","label":"Both cost the same in interest; only the payment size differs.","feedback":"[Research-backed] The rate is the same but the time is not — and interest is rate × balance × time. More time at similar balances means more interest, full stop."},{"id":"d","label":"The 36-month loan costs more because you pay it off faster.","feedback":"[Research-backed] Backwards. Faster payoff means fewer months of interest accruing. Speed is what saves the ~$1,350."}],"correct":"a"},{"verb":"predict","basis":"research","prompt":"Jordan’s car payment is $400/month. He switches to paying $200 every two weeks. Predict the yearly result.","choices":[{"id":"a","label":"26 half-payments = $10,400 a year = 13 full monthly payments. That 13th payment attacks principal directly and shrinks all future interest.","feedback":"[Research-backed] Right — plain arithmetic: 26 × $200 = $10,400, which is 13 × $400. One extra full payment a year, straight at principal, with zero extra budget pain."},{"id":"b","label":"12 full payments — biweekly is just a different schedule with the same total.","feedback":"[Research-backed] Count the weeks: 52 weeks ÷ 2 = 26 payments, not 24. Those two extra half-payments are the whole trick."},{"id":"c","label":"24 half-payments = 12 full payments, so nothing changes.","feedback":"[Research-backed] There are 52 weeks in a year, not 48. 26 half-payments is 13 full ones — the miscount hides the free payment."},{"id":"d","label":"13 payments, but the extra one is pure bank profit.","feedback":"[Research-backed] The extra payment reduces YOUR principal, which reduces YOUR future interest. It is the opposite of bank profit — it is interest you never pay."}],"correct":"a"},{"verb":"explain","basis":"research","prompt":"Explain why a $2,000 balance at 22% barely moves when Liam pays only the ~$40 minimum.","choices":[{"id":"a","label":"About $37 of that $40 is interest ($2,000 × 22% ÷ 12). Only ~$3 hits the balance — the debt mostly stands still while interest piles on.","feedback":"[Research-backed] Right. This is the shape of the minimum-payment trap: the payment is sized to barely cover interest, so the balance survives for decades and the total interest can exceed the original debt many times over."},{"id":"b","label":"The bank pockets the minimum as a fee.","feedback":"[Research-backed] The $40 is not a fee — ~$37 of it is the month’s interest charge on the balance. The trap is structural (payment ≈ interest), not a hidden fee."},{"id":"c","label":"The balance drops $40 every month; it is just slow.","feedback":"[Research-backed] It drops ~$3, not $40, because interest eats the payment first. At that pace the payoff stretches into decades."},{"id":"d","label":"Interest pauses while you make minimum payments.","feedback":"[Research-backed] Interest never pauses — it accrues on the remaining balance every single month, minimum payment or not."}],"correct":"a"},{"verb":"mc","basis":"research","prompt":"Same $2,000 balance at 22%. Which payment plan actually kills it?","choices":[{"id":"a","label":"Pay a fixed $80/month: done in about 3 years with ~$700 in interest — versus decades and $10,000+ in interest on minimums alone.","feedback":"[Research-backed] Right. Doubling the payment from ~$40 to a fixed $80 collapses the timeline from decades to about 3 years and erases roughly $9,000+ of interest. The example numbers are rounded; the shape is the lesson."},{"id":"b","label":"Pay the shrinking minimum — cheapest, because the payments get smaller over time.","feedback":"[Research-backed] Shrinking payments are the trap itself: as the payment shrinks toward the interest charge, progress stalls and the debt can outlive the purchase by decades."},{"id":"c","label":"Pay $40 one month, skip the next — it averages out.","feedback":"[Research-backed] Skipped months add late fees and a missed-payment mark on the 35%-of-score payment history — plus a full month of uninterrupted interest."},{"id":"d","label":"Pay just the $37 interest so the balance never grows.","feedback":"[Research-backed] “Never grows” is not “shrinks.” Interest-only payments are a treadmill — you pay forever and owe the same $2,000 at the end."}],"correct":"a"},{"verb":"decide","basis":"street","prompt":"Two payoff plans cost about the same on paper. Maya picks the snowball anyway. Decide why that can be the smarter call.","choices":[{"id":"a","label":"Killing the first small debt fast gives a visible win — and wins are what keep people paying month after month.","feedback":"[Street-smart] Right. Debt payoff is a behavior problem wearing a math costume. The plan you finish beats the plan you quit — and early wins are what keep people in the fight."},{"id":"b","label":"The snowball has secret lower interest rates.","feedback":"[Street-smart] No secrets — the rates are whatever your statements say. The snowball’s power is psychological, not financial engineering."},{"id":"c","label":"Small debts charge no interest.","feedback":"[Street-smart] Small debts absolutely charge interest — often at the highest rates you have. Size and rate are different things."},{"id":"d","label":"It lets her ignore the big debts entirely.","feedback":"[Street-smart] The snowball never ignores anything: minimums on every debt, every month. Ignoring debts is how collections happen."}],"correct":"a"},{"verb":"predict","basis":"street","prompt":"Maya’s snowball is rolling: she kills the $400 store card. Its $25 minimum is now free, on top of her $200 extra. Predict the snowball move.","choices":[{"id":"a","label":"Roll the whole $225 into the next-smallest debt — the monthly attack grows with every kill.","feedback":"[Street-smart] Right. $60 minimum + $225 rolled = $285/month against the $2,500 card. Each payoff makes the next one faster — that accelerating roll is why it is called a snowball."},{"id":"b","label":"Spend the freed $25 — she earned a reward.","feedback":"[Street-smart] Lifestyle creep eats snowballs. The freed payment is ammunition, not a raise — spend it and the roll stops."},{"id":"c","label":"Keep sending $25 to the dead store card as savings.","feedback":"[Street-smart] The dead card needs $0. Every dollar sent to a $0 balance is a dollar not killing a live debt that is charging interest right now."},{"id":"d","label":"Drop her total debt payment back to minimums — one win is enough.","feedback":"[Street-smart] One win is the start, not the finish. Shrinking the attack after the first kill throws away the entire compounding effect."}],"correct":"a"},{"verb":"decide","basis":"research","prompt":"Liam owes $2,000 on a card at 22% APR. Month one, the minimum is about $40 — and about $37 of it is interest. Only ~$3 touches the balance. What should he do?","choices":[{"id":"t0c0","label":"Pay a fixed $80/month: done in about 3 years with ~$700 in interest, instead of decades and $10,000+ on minimums alone.","feedback":"[Research-backed] Right. A fixed $80 collapses the timeline from decades to about 3 years and erases roughly $9,000 of interest. Same debt, different plan, completely different life. [Research-backed] Minimum payments shrink with the balance, so the payment converges toward the interest charge and progress stalls. Fixed payments larger than the minimum break the stall — the extra goes straight at principal, which shrinks every future interest charge."},{"id":"t0c1","label":"Keep paying the minimum — the payments shrink as the balance shrinks, so it gets cheaper over time.","feedback":"[Research-backed] Run the month-one split: $40 in, $37 eaten by interest, $3 off the balance. Any plan that does not beat that split is the trap wearing a different hat."},{"id":"t0c2","label":"Pay $40 this month and skip next month to catch up — it averages out.","feedback":"[Research-backed] Run the month-one split: $40 in, $37 eaten by interest, $3 off the balance. Any plan that does not beat that split is the trap wearing a different hat."},{"id":"t0c3","label":"Pay just the $37 of interest so the balance never grows.","feedback":"[Research-backed] Run the month-one split: $40 in, $37 eaten by interest, $3 off the balance. Any plan that does not beat that split is the trap wearing a different hat."}],"correct":"t0c0"},{"verb":"predict","basis":"research","prompt":"Maya snowballs three debts: a $400 store card (min $25), a $2,500 card (min $60), a $6,000 loan (min $130) — plus $200 extra aimed at the smallest. The store card dies in month two. Predict what happens to her attack next.","choices":[{"id":"t1c0","label":"It rolls forward: $60 minimum + $225 freed up = $285/month against the $2,500 card until that one dies too.","feedback":"[Research-backed] Right. Every kill frees its payment into the attack, so $285/month hits the second card, then an even bigger number hits the loan. The roll is the method. [Research-backed] This is the compounding that makes the snowball work: each payoff increases the monthly attack on the next debt, so later debts fall faster than the first one did. Minimums-only never compounds — that is why it takes roughly 7 years and ~$4,600 in interest on these three debts, versus about 2½ years and ~$1,500 with the $200 snowball."},{"id":"t1c1","label":"She pockets the $225 as a reward for the win.","feedback":"[Research-backed] Check the snowball rule: minimums on all, extra at the smallest — and when one dies, its whole payment joins the extra. Nothing gets pocketed or split."},{"id":"t1c2","label":"She drops back to minimums on everything — one win was the goal.","feedback":"[Research-backed] Check the snowball rule: minimums on all, extra at the smallest — and when one dies, its whole payment joins the extra. Nothing gets pocketed or split."},{"id":"t1c3","label":"She splits the $225 across the two remaining debts to be fair.","feedback":"[Research-backed] Check the snowball rule: minimums on all, extra at the smallest — and when one dies, its whole payment joins the extra. Nothing gets pocketed or split."}],"correct":"t1c0"}],"student-loans":[{"verb":"decide","basis":"research","prompt":"Liam was awarded $9,000 in federal loans and a $9,000 private loan from his bank. Tuition gap is $9,000. Rules are changing through 2028 — verify at StudentAid.gov. Which move?","choices":[{"id":"a","label":"Take the $9,000 federal loan; decline the private loan.","feedback":"[Research-backed] Federal first, always. The private loan adds nothing he needs and removes every federal protection."},{"id":"b","label":"Take the private loan — bank rates look friendlier.","feedback":"[Research-backed] Friendly-looking rates hide variable terms and zero federal protections."},{"id":"c","label":"Take both and invest the extra $9,000.","feedback":"[Research-backed] Borrowing to invest is gambling with debt. Invest money you own, not money you owe."},{"id":"d","label":"Take neither; put tuition on a credit card.","feedback":"[Research-backed] Credit-card interest dwarfs any student-loan rate. This is the worst of the four options."}],"correct":"a"},{"verb":"spot","basis":"research","prompt":"One of these statements is FALSE. Spot it.","choices":[{"id":"a","label":"Federal loans offer income-driven repayment plans.","feedback":"[Research-backed] This one is TRUE — income-driven plans are a federal-loan feature."},{"id":"b","label":"You can still enroll in the SAVE plan today.","feedback":"[Research-backed] FALSE — this is the one. SAVE was vacated by a court in March 2026 and terminated by statute. No new enrollment, period."},{"id":"c","label":"Private loans generally require a co-signer.","feedback":"[Research-backed] This one is TRUE — most private lenders demand a co-signer because students have thin credit files."},{"id":"d","label":"Parent PLUS loans have per-year and lifetime caps.","feedback":"[Research-backed] This one is TRUE — $20,000 a year per student, $65,000 total, since July 2026."}],"correct":"b"},{"verb":"compare","basis":"research","prompt":"Maya graduates with federal loans and a low starting salary. Compare: RAP (1%–10% of AGI, balance cannot grow while paying) vs the standard 10-year plan. Which fits a lean first year better, and why?","choices":[{"id":"a","label":"RAP — payments scale with income and the balance stays put.","feedback":"[Research-backed] RAP ties payments to what she actually earns and stops the balance from growing while she pays. Built for lean years."},{"id":"b","label":"Standard plan — fixed payments build discipline.","feedback":"[Research-backed] Discipline does not pay rent. A fixed payment she cannot afford leads to missed payments, not character."},{"id":"c","label":"They are identical in a low-income year.","feedback":"[Research-backed] They are not identical: the standard plan charges the same no matter what she earns; RAP drops with her income."},{"id":"d","label":"Neither — defer everything and pay nothing.","feedback":"[Street-smart] Deferment pauses payments, it does not erase the debt — and forbearance months do not count toward PSLF. Use the tools, do not hide from the loan."}],"correct":"a"},{"verb":"predict","basis":"research","prompt":"Jordan loses her job six months after graduation. She has federal loans on an income-driven plan. Predict what happens to her payments.","choices":[{"id":"a","label":"Her payments can drop to the plan minimum — $10 a month on RAP — and the balance cannot grow.","feedback":"[Research-backed] Income-driven plans recalculate with income. RAP sets a $10 floor and blocks the balance from growing while she pays."},{"id":"b","label":"Her payments stay exactly the same; lenders do not care.","feedback":"[Research-backed] That is how private loans behave. Federal income-driven plans adjust with income — that is the whole point."},{"id":"c","label":"The loans are cancelled automatically after 90 days unemployed.","feedback":"[Research-backed] No loan cancels itself for unemployment. She must request deferment or an income-driven recalculation."},{"id":"d","label":"Her co-signer is billed instead.","feedback":"[Research-backed] Federal loans do not use co-signers. That is a private-loan feature."}],"correct":"a"},{"verb":"explain","basis":"research","prompt":"Explain why the July 2026 elimination of Grad PLUS loans matters for someone starting a master's degree.","choices":[{"id":"a","label":"Grad students lost their main way to borrow the full cost of attendance — now grad borrowing caps at $20,500 a year.","feedback":"[Research-backed] Exactly. Grad PLUS covered the gap between other aid and full cost. With it gone and a $20,500 cap, expensive programs need scholarships, savings, or a cheaper school."},{"id":"b","label":"Grad students can no longer borrow anything at all.","feedback":"[Research-backed] They can still borrow — capped at $20,500 a year ($100,000 lifetime). The cap is the story, not a ban."},{"id":"c","label":"It only matters for medical students.","feedback":"[Research-backed] Professional programs have their own $50,000 cap. Grad PLUS covered all graduate programs, so all of them feel this."},{"id":"d","label":"It does not matter; private loans are cheaper anyway.","feedback":"[Research-backed] Private loans lack income-driven plans, PSLF, and deferment. Cheaper-looking is not cheaper when the terms turn against you."}],"correct":"a"},{"verb":"mc","basis":"research","prompt":"Under the July 2026 rules, what is the Parent PLUS borrowing limit?","choices":[{"id":"a","label":"$20,000 a year per student, $65,000 total.","feedback":"[Research-backed] Correct — and those caps are why expensive schools now require a real funding plan, not just loans."},{"id":"b","label":"$50,000 a year, no lifetime cap.","feedback":"[Research-backed] $50,000 a year is the professional-school cap. Parent PLUS is $20,000 a year per student, $65,000 total."},{"id":"c","label":"$100,000 lifetime per family.","feedback":"[Research-backed] $100,000 lifetime is the graduate-school cap, not Parent PLUS."},{"id":"d","label":"Unlimited, like before.","feedback":"[Research-backed] The old uncapped days ended July 2026. Rules are changing through 2028 — verify at StudentAid.gov."}],"correct":"a"},{"verb":"decide","basis":"street","prompt":"Liam has two weeks before three scholarship deadlines: one $500 local award from a hardware store, one $500 local award from the Rotary club, one $10,000 national award. He has time to do two applications well. Decide.","choices":[{"id":"a","label":"Apply to both local awards — less competition, real odds.","feedback":"[Street-smart] Small local awards draw dozens of applicants, not thousands. Two real shots beat one lottery ticket."},{"id":"b","label":"Apply to the national award only — $10,000 beats $500.","feedback":"[Street-smart] The national pool has thousands of applicants. Expected value favors the winnable local awards."},{"id":"c","label":"Apply to one local and the national, half-effort each.","feedback":"[Street-smart] Deadlines matter more than perfection — but a rushed application is a wasted application. Do two well, not three badly."},{"id":"d","label":"Skip all three; scholarships are too much work.","feedback":"[Street-smart] A $500 local award for three hours of work is over $150 an hour. Find a job that pays that."}],"correct":"a"},{"verb":"compare","basis":"street","prompt":"Maya wants a master's at a school costing $40,000 a year. Federal grad borrowing caps at $20,500 a year. Compare her two realistic options.","choices":[{"id":"a","label":"Cover the $19,500 gap with scholarships, savings, or a cheaper program — not private loans by default.","feedback":"[Street-smart] The cap is a warning, not a suggestion to borrow privately. Scholarships, employer tuition help, or a cheaper accredited program beat private debt."},{"id":"b","label":"Borrow the $19,500 gap in private loans each year — same thing.","feedback":"[Research-backed] Not the same thing: private loans have no income-driven plans, no PSLF, often variable rates, and usually need a co-signer."},{"id":"c","label":"Drop the master's — $20,500 a year means grad school is impossible.","feedback":"[Street-smart] The cap limits borrowing, not education. Plenty of master's programs cost under $20,500 a year, and assistantships exist."},{"id":"d","label":"Ask her parents to take the gap in Parent PLUS.","feedback":"[Research-backed] Parent PLUS is capped too ($20,000 a year per student, $65,000 total) — and it puts the debt on her parents, not her."}],"correct":"a"},{"verb":"decide","basis":"research","prompt":"Maya has $9,000 in scholarships and a $16,000 gap. She qualifies for federal loans to cover it. A private lender offers a slightly lower starting rate. What does she do?","choices":[{"id":"t0c0","label":"Take the federal loans; skip the private loan.","feedback":"Right. Federal loans carry income-driven plans and deferment; the private loan's lower teaser rate buys none of that. [Research-backed] Federal loans include income-driven repayment, PSLF eligibility, and deferment. Private loans include none of those — terms are set by the lender, often variable, usually with a co-signer."},{"id":"t0c1","label":"Take the private loan for the lower rate.","feedback":"Not quite — look past the starting rate. Which loan still helps her if her income drops to zero?"},{"id":"t0c2","label":"Borrow both and pocket the difference.","feedback":"Not quite — look past the starting rate. Which loan still helps her if her income drops to zero?"},{"id":"t0c3","label":"Put the gap on a credit card.","feedback":"Not quite — look past the starting rate. Which loan still helps her if her income drops to zero?"}],"correct":"t0c0"},{"verb":"spot","basis":"street","prompt":"Liam can apply to three scholarships this week: a $400 local award, a $750 local award, and a $15,000 national award. He has time for two strong applications. Spot the smart play.","choices":[{"id":"t1c0","label":"Both local awards — less competition, real odds.","feedback":"Exactly. Local awards draw dozens of applicants; national ones draw thousands. Deadlines matter more than perfection. [Street-smart] Small local scholarships are often less competitive. Apply to all three levels, and never trade two winnable applications for one lottery ticket."},{"id":"t1c1","label":"The national award only — biggest prize.","feedback":"Think like an odds-maker: would you rather be 1 of 40 or 1 of 4,000?"},{"id":"t1c2","label":"One local and the national, rushed.","feedback":"Think like an odds-maker: would you rather be 1 of 40 or 1 of 4,000?"},{"id":"t1c3","label":"Skip them all.","feedback":"Think like an odds-maker: would you rather be 1 of 40 or 1 of 4,000?"}],"correct":"t1c0"}],"retirement":[{"verb":"decide","basis":"research","prompt":"Jordan's first job matches 50% up to 6% of her pay. She earns $40,000. She is deciding how much of her paycheck to contribute to the 401(k). What is the right first move?","choices":[{"id":"a","label":"Contribute 6% — capture the full match before anything else.","feedback":"[Research-backed] 6% of $40,000 is $2,400 from her; the match adds $1,200 — an instant 50% return. No investment beats that first."},{"id":"b","label":"Contribute 3% — half the match is fine for now.","feedback":"[Research-backed] 3% leaves $600 of free money on the table every year. That is a raise she declined."},{"id":"c","label":"Contribute 0% — she needs the cash more at 22.","feedback":"[Research-backed] The match is a guaranteed 50% return. No short-term want beats it."},{"id":"d","label":"Contribute 15% — more is always better.","feedback":"[Street-smart] 15% is great eventually, but the FIRST rule is the full match. Capture the free money, then scale up."}],"correct":"a"},{"verb":"compare","basis":"research","prompt":"Compare: Maya, 25, low tax bracket, chooses a Roth IRA. Liam, 55, high tax bracket, chooses a Traditional 401(k). Who picked the better account type for their situation?","choices":[{"id":"a","label":"Both picked well — Roth fits low brackets, Traditional fits high brackets.","feedback":"[Research-backed] Maya pays little tax now, so tax-free growth later wins. Liam gets a big deduction at his high rate now. Match the account to the bracket."},{"id":"b","label":"Maya should have picked Traditional — tax breaks are always better.","feedback":"[Research-backed] A deduction is worth your tax rate. At Maya's low rate, the deduction is tiny and she gives up decades of tax-free growth."},{"id":"c","label":"Liam should have picked Roth — tax-free is always better.","feedback":"[Research-backed] At Liam's high bracket, the Traditional deduction saves real money now. Roth is not automatically better."},{"id":"d","label":"It makes no difference which they pick.","feedback":"[Research-backed] It makes a large difference: the same $7,500 can leave you with very different after-tax money depending on bracket and timing."}],"correct":"a"},{"verb":"predict","basis":"research","prompt":"$100 a month into a Roth from 18 to 65 at an illustrative 7% average growth ends near $380,000+ tax-free. Starting at 28 instead lands near $210,000. Predict: what does waiting until 38 cost versus starting at 18?","choices":[{"id":"a","label":"Far more than the 28-vs-18 gap — each skipped decade costs worse than the last.","feedback":"[Research-backed] Compounding is back-loaded: the biggest growth happens in the final decades, and those decades grow out of the early dollars. Skip the early years and you skip the engine."},{"id":"b","label":"About the same as starting at 28 — ten years is ten years.","feedback":"[Research-backed] Compounding is not linear. The 18-to-28 dollars compound for 47 years; the 28-to-38 dollars compound for 37. Earlier years are worth more."},{"id":"c","label":"Less than the 28-vs-18 gap — later dollars are worth more.","feedback":"[Research-backed] Later dollars compound for FEWER years. Every decade you skip costs more than the one before it."},{"id":"d","label":"Nothing — you can just contribute more at 38 to catch up.","feedback":"[Research-backed] Run the math: catching up 20 lost years at 7% takes roughly triple the monthly contribution. Time is not for sale at any price."}],"correct":"a"},{"verb":"explain","basis":"research","prompt":"Explain in one line why \"always capture the full employer match first\" is the right rule.","choices":[{"id":"a","label":"It is an instant, guaranteed return — e.g., 50% on day one — that no investment can beat.","feedback":"[Research-backed] A 50% match is a 50% return before the market does anything. That is the definition of free money."},{"id":"b","label":"Because the IRS requires you to take the match.","feedback":"[Research-backed] The IRS requires nothing. The rule is about math, not law."},{"id":"c","label":"Because your employer will fire you if you skip it.","feedback":"[Research-backed] No employer fires you for skipping the match. They just keep the money you refused."},{"id":"d","label":"Because matching funds are tax-free forever.","feedback":"[Research-backed] Match money is taxed like the rest of the account. The magic is the instant return, not the taxes."}],"correct":"a"},{"verb":"spot","basis":"street","prompt":"Spot the bad advice:","choices":[{"id":"a","label":"Retirement can wait until you are 40 — focus on fun money now.","feedback":"[Street-smart] This is the bad advice. Waiting until 40 throws away the 22 most powerful compounding years. Fun money now costs fortune money later."},{"id":"b","label":"Capture the full employer match from your first paycheck.","feedback":"[Street-smart] This is GOOD advice — the match is free money from day one."},{"id":"c","label":"Learn Roth vs Traditional before your first real job.","feedback":"[Street-smart] This is GOOD advice — the account choice you make at 22 echoes for 40 years."},{"id":"d","label":"Small monthly contributions beat waiting to invest \"big\" later.","feedback":"[Street-smart] This is GOOD advice — $100 a month at 18 beats $300 a month at 38."}],"correct":"a"},{"verb":"mc","basis":"research","prompt":"In 2026, the IRA contribution limit for someone under 50 is:","choices":[{"id":"a","label":"$7,500 a year.","feedback":"[Research-backed] Correct — $7,500 under 50, $8,600 at 50+. Limits change most years, so check the IRS."},{"id":"b","label":"$24,500 a year.","feedback":"[Research-backed] $24,500 is the 401(k) limit. IRA and 401(k) are different accounts with different caps."},{"id":"c","label":"$8,600 a year for everyone.","feedback":"[Research-backed] $8,600 is the 50-and-older IRA limit. Under 50 it is $7,500."},{"id":"d","label":"There is no limit on IRAs.","feedback":"[Research-backed] There is a limit every year — $7,500 in 2026 for under-50. Over-contributing triggers penalties."}],"correct":"a"},{"verb":"compare","basis":"research","prompt":"Maya opens a Roth IRA at 20. Compare withdrawing all of it at 55 vs at 60.","choices":[{"id":"a","label":"At 60 the earnings are tax-free (59½ + 5-year rule met); at 55 she may owe tax and penalties on earnings.","feedback":"[Research-backed] Roth earnings are tax-free only after 59½ AND 5 years with the account open. At 55 she misses the age rule."},{"id":"b","label":"No difference — Roth withdrawals are always tax-free.","feedback":"[Research-backed] Contributions come out anytime tax-free, but EARNINGS need the 59½ + 5-year rules. That is the deal for tax-free growth."},{"id":"c","label":"At 55 it is tax-free but at 60 she pays tax.","feedback":"[Research-backed] Backwards. The 59½ rule protects later withdrawals, not earlier ones."},{"id":"d","label":"She cannot withdraw anything before 65.","feedback":"[Research-backed] She can withdraw her contributions anytime. The 59½ + 5-year rules apply to earnings."}],"correct":"a"},{"verb":"decide","basis":"street","prompt":"Liam is 12. He cannot open an IRA or 401(k) yet. What is his best move right now?","choices":[{"id":"a","label":"Build the saving habit and learn the rules now, so he acts on day one of his first job.","feedback":"[Street-smart] Knowing this at 12 beats learning it at 32. The habit and the knowledge compound before the money does."},{"id":"b","label":"Do nothing — retirement is 50 years away.","feedback":"[Street-smart] That is exactly how people end up learning at 32 what Liam could know at 12."},{"id":"c","label":"Open a Roth IRA in his own name today anyway.","feedback":"[Research-backed] Minors cannot open IRAs on their own — it takes earned income and an adult custodian. Learn now, open when eligible."},{"id":"d","label":"Borrow money to \"start early\" on investing.","feedback":"[Street-smart] Borrowing to invest is not starting early, it is starting in debt."}],"correct":"a"},{"verb":"decide","basis":"research","prompt":"Jordan, 22, earns $40,000. Her job matches 50% up to 6% of pay. She is deciding her 401(k) contribution. What is the right first move?","choices":[{"id":"t0c0","label":"Contribute 6% to capture the full match.","feedback":"Right. 6% of $40,000 is $2,400 from her plus $1,200 free from the match — an instant 50% return before the market moves. [Research-backed] An employer match is an instant, guaranteed return — e.g., 50% — that no investment beats. Always capture the full match first."},{"id":"t0c1","label":"Contribute 3% — half is fine for now.","feedback":"Run the match math: 50% of her 6% contribution is free money. What beats a guaranteed 50% on day one?"},{"id":"t0c2","label":"Contribute 0% — she needs the cash.","feedback":"Run the match math: 50% of her 6% contribution is free money. What beats a guaranteed 50% on day one?"},{"id":"t0c3","label":"Skip the 401(k) and pick stocks herself.","feedback":"Run the match math: 50% of her 6% contribution is free money. What beats a guaranteed 50% on day one?"}],"correct":"t0c0"},{"verb":"compare","basis":"research","prompt":"Compare $100/month from 18 to 65 (~$380,000+) vs from 28 to 65 (~$210,000) at an illustrative 7% growth. What does the comparison prove?","choices":[{"id":"t1c0","label":"Time matters more than amount — the early decade is worth ~$170,000.","feedback":"Exactly. Same $100, same 7% — the only difference is ten early years, and they are worth roughly $170,000. [Research-backed] Compounding is back-loaded: early dollars compound the longest, so each skipped decade costs more than the last. (7% is an illustrative assumption; actual returns vary.)"},{"id":"t1c1","label":"The amounts are close enough that timing barely matters.","feedback":"Hold the two end numbers side by side: ~$380,000 vs ~$210,000. Same payment, same growth. What is the only thing that changed?"},{"id":"t1c2","label":"Starting later is better because the dollars are fresher.","feedback":"Hold the two end numbers side by side: ~$380,000 vs ~$210,000. Same payment, same growth. What is the only thing that changed?"},{"id":"t1c3","label":"You can always catch up by contributing more later.","feedback":"Hold the two end numbers side by side: ~$380,000 vs ~$210,000. Same payment, same growth. What is the only thing that changed?"}],"correct":"t1c0"}],"shopping-smart":[{"verb":"decide","basis":"street","prompt":"Jordan needs five things at the store. It is 9pm, he is exhausted, and his list is on the counter at home. What is his best move?","choices":[{"id":"wait","label":"Go tomorrow with the list — shopping tired with no list is how extra stuff lands in the cart","feedback":"[Street-smart] Correct. Decision fatigue is real: the longer and tireder the trip, the more impulse buys slip in. Waiting costs nothing; the cart costs plenty."},{"id":"phone","label":"Go now but buy only what he remembers — his memory is sharp","feedback":"[Street-smart] Memory is not a plan. A tired brain shopping from memory is exactly how the cart fills up with things he never needed."},{"id":"aisles","label":"Go now and walk every aisle so he does not forget anything","feedback":"[Street-smart] Wandering every aisle is the opposite of a plan — more time in the store means more tired decisions and more impulse buys."},{"id":"willpower","label":"Go now — a strong person can resist any temptation","feedback":"[Street-smart] Willpower is the thing that is already depleted at 9pm. Systems beat willpower: list, full stomach, rested brain."}],"correct":"wait"},{"verb":"spot","basis":"street","prompt":"Maya opens her store app: 40% off a $20 face serum. She has never bought face serum and does not need it. She says \"I am saving $8!\" What is the real story?","choices":[{"id":"no-savings","label":"She is not saving $8 — she is spending $12 on something she would never buy","feedback":"[Street-smart] Correct. A coupon only saves money on something you were already going to buy. On anything else, it is a discount on spending, not saving."},{"id":"smart","label":"She is saving — 40% off is real money she keeps","feedback":"[Street-smart] She keeps nothing: the money leaves her pocket for a product she did not want before the coupon existed. The coupon created the purchase, not the need."},{"id":"free","label":"It is practically free with 40% off","feedback":"[Street-smart] $12 out of pocket is not free. \"Discount\" is not \"zero\" — the full price of things you do not need is zero."},{"id":"stack","label":"She should buy two and stack the savings","feedback":"[Street-smart] Doubling an unneeded purchase doubles the waste, not the savings. Two unwanted serums is $24 spent to \"save\" $16."}],"correct":"no-savings"},{"verb":"compare","basis":"street","prompt":"Gas is 5¢ cheaper at a station 10 extra minutes away. On a 12-gallon fill that saves about 60¢. The detour burns roughly $1 of gas and 20 minutes of Jordan's time. What should Jordan do?","choices":[{"id":"skip","label":"Skip the detour — spending $1 and 20 minutes to \"save\" 60¢ is losing money","feedback":"[Street-smart] Correct. 60¢ saved minus $1 in gas is a 40¢ loss before counting 20 minutes. Do the math before chasing the price."},{"id":"chase","label":"Chase the cheaper price — saving 5¢ a gallon always pays off","feedback":"[Street-smart] 5¢ times 12 gallons is only 60¢ — small per-unit savings need big volumes to matter. On a normal fill, the detour costs more than it saves."},{"id":"double","label":"Go twice — two cheap fills beat one expensive one","feedback":"[Street-smart] Two detours doubles the loss: about $2 of gas and 40 minutes to save $1.20. Arithmetic does not improve with repetition."},{"id":"idling","label":"Drive there slowly with the engine idling to burn less gas","feedback":"[Street-smart] Idling still burns gas, and 20 extra minutes is gone either way. The math loses before driving style enters the picture."}],"correct":"skip"},{"verb":"explain","basis":"street","prompt":"An online store offers free shipping on orders over $35. Maya's cart is $28, and shipping is $5. She adds a $12 phone case she barely wants to hit $35. Explain the math.","choices":[{"id":"loses","label":"She spent $12 to \"save\" $5 on shipping — she is $7 worse off than paying the shipping","feedback":"[Street-smart] Correct. Paying $5 shipping costs $33 total; adding the case costs $40 total. The \"free shipping\" made her spend more, which is exactly what the threshold was designed to do."},{"id":"saves","label":"She saved money — she got a free phone case and free shipping","feedback":"[Street-smart] Nothing was free. Her total went from $33 to $40. \"Free shipping\" is only free when you spend more than you planned."},{"id":"case","label":"She won — the phone case is a good deal at $12","feedback":"[Street-smart] Maybe the case is fine, but she bought it to unlock shipping, not because she wanted it. The question is the $5 shipping versus the $12 add-on — and the add-on costs $7 more."},{"id":"return","label":"She can return the case later and keep the free shipping","feedback":"[Street-smart] Most stores revoke or reduce the free shipping when the order drops below the threshold after a return. The trick fails on the way back too."}],"correct":"loses"},{"verb":"predict","basis":"street","prompt":"Liam finds noise-cancelling headphones for $9 on a marketplace app with shipping in 2–4 weeks and returns that cost almost as much as the item. He needs headphones for a school trip THIS Friday. Predict what happens if he orders.","choices":[{"id":"misses","label":"He misses the trip deadline and has no cheap return path — the \"deal\" was not cheap for HIS situation","feedback":"[Street-smart] Correct. A deal includes arrival time and return hassle. If you need it by Friday, the cheap option that arrives in three weeks is not cheap — it is a missed deadline."},{"id":"fine","label":"It works out — $9 headphones are a steal no matter what","feedback":"[Street-smart] $9 is only a steal if the product arrives when needed and can be returned if broken. Neither is true here."},{"id":"faster","label":"He can pay for faster shipping and still come out ahead","feedback":"[Street-smart] Express shipping on a $9 item usually wipes out the discount entirely — and returns are still painful. The deal was built on cheap slow shipping."},{"id":"quality","label":"Cheap marketplace items are always lower quality, so he should never order there","feedback":"[Street-smart] Too absolute — some marketplace buys are fine when time does not matter. The point is matching the purchase to the deadline, not banning the platform."}],"correct":"misses"},{"verb":"decide","basis":"street","prompt":"Jordan finds a used gaming console on Marketplace for half the store price. The seller wants payment wired ahead and says \"no meetups, I will mail it.\" What does Jordan do?","choices":[{"id":"walk","label":"Walk away — wiring money ahead with no meetup is the classic scam setup","feedback":"[Street-smart] Correct. The rules exist for this exact moment: meet in public, test electronics before paying, never wire money ahead. If a deal feels wrong, walking away costs nothing and saves everything."},{"id":"wire","label":"Wire the money — half price is too good to risk losing","feedback":"[Street-smart] \"Too good to risk losing\" is the pressure the scammer is counting on. Once money is wired, it is gone — and a seller who refuses meetups has something to hide."},{"id":"partial","label":"Wire half now, half later — a compromise keeps the deal alive","feedback":"[Street-smart] Half a scam is still a scam. Compromise works with honest sellers, not with someone refusing every safety rule."},{"id":"mail","label":"Trust the mail — the platform probably guarantees it","feedback":"[Street-smart] Marketplace platforms generally do NOT cover off-platform wire payments. \"Probably guaranteed\" is doing a lot of heavy lifting in that plan."}],"correct":"walk"},{"verb":"compare","basis":"research","prompt":"Maya compares two jars of peanut butter. Jar A is 16 oz for $3.20. Jar B is 28 oz for $4.90. The shelf tag shows A at 20¢/oz and B at 17.5¢/oz. Which is the better value, and why?","choices":[{"id":"b","label":"Jar B — the per-ounce price (17.5¢ vs 20¢) tells the truth when package sizes differ","feedback":"[Research-backed] Correct. The unit price strips away packaging tricks: B costs 2.5¢ less per ounce. The big jar is not \"more expensive\" — the shelf tag proves it is cheaper per bite."},{"id":"a","label":"Jar A — the smaller total price means it is cheaper","feedback":"[Research-backed] $3.20 at checkout is less, but you get less food per dollar. Confusing the smaller price tag with the better value is exactly what bulk packaging counts on."},{"id":"size","label":"The bigger jar is always a worse deal — stores charge more for big sizes","feedback":"[Research-backed] \"Always\" is doing the work here, and it is wrong. That is why the unit price exists: to check each time instead of guessing by size."},{"id":"brand","label":"Pick whichever brand is on sale, price tags do not matter","feedback":"[Research-backed] Sale tags matter less than the per-unit math. A sale price on a worse per-ounce deal can still lose to the regular-priced option."}],"correct":"b"},{"verb":"spot","basis":"street","prompt":"Liam shops right after school, starving. His list says \"pasta, sauce, apples.\" He keeps adding snacks, frozen pizza, and cookies. What pattern is happening?","choices":[{"id":"hunger","label":"Hunger hijacking — his stomach is writing the list now, not the plan he made at home","feedback":"[Street-smart] Correct. Shopping hungry is a documented trap: the brain treats everything as urgent fuel. The fix is free — eat first, then shop the list."},{"id":"cravings","label":"He just loves food — personality, not a pattern","feedback":"[Street-smart] Personality did not change between writing the list and shopping. What changed is his blood sugar. Same brain, different fuel level, different cart."},{"id":"willpower","label":"He lacks willpower and should build more of it","feedback":"[Street-smart] The willpower answer again. He had a plan; hunger ate the plan. Systems — a snack before the store — beat another lecture on discipline."},{"id":"prices","label":"The snacks must be good deals — the store put them on sale","feedback":"[Street-smart] Sale or not, they were not on his list and he only wants them because he is hungry. \"Good deal on an unplanned buy\" is still an unplanned buy."}],"correct":"hunger"},{"verb":"compare","basis":"research","prompt":"Granola: Bag X is 12 oz for $4.20 (35¢/oz). Bag Y is 20 oz for $6.00 (30¢/oz). Which is the better value?","choices":[{"id":"t0c0","label":"Bag Y — 30¢ per ounce beats 35¢ per ounce","feedback":"Right — the shelf tag did the math for you. [Research-backed] Unit price removes the packaging illusion. Per ounce is the only apples-to-apples comparison when sizes differ."},{"id":"t0c1","label":"Bag X — $4.20 is less money out of pocket","feedback":"Check the per-ounce numbers again: 30¢ vs 35¢."},{"id":"t0c2","label":"They are the same — both are granola","feedback":"Check the per-ounce numbers again: 30¢ vs 35¢."},{"id":"t0c3","label":"The bigger bag is always a ripoff","feedback":"Check the per-ounce numbers again: 30¢ vs 35¢."}],"correct":"t0c0"},{"verb":"decide","basis":"street","prompt":"A station 8 minutes away sells gas 4¢ cheaper per gallon. On a 12-gallon fill that saves about 48¢. The round trip burns roughly $1 of gas. Go or skip?","choices":[{"id":"t1c0","label":"Skip — spending $1 to save 48¢ is a loss","feedback":"Exactly — the arithmetic decides, not the price sign. [Street-smart] Small per-gallon discounts need huge volumes to matter. On a normal fill, the detour almost always costs more than it saves."},{"id":"t1c1","label":"Go — every cent off the gallon counts","feedback":"48¢ saved minus $1 spent = a 52¢ loss."},{"id":"t1c2","label":"Go on the way home so it does not count","feedback":"48¢ saved minus $1 spent = a 52¢ loss."},{"id":"t1c3","label":"Go twice and the savings double","feedback":"48¢ saved minus $1 spent = a 52¢ loss."}],"correct":"t1c0"}],"the-gap":[{"verb":"explain","basis":"street","prompt":"Maya aced every quiz in this app. Her first real month brings a tired Friday, friends pushing a night out, and a surprise phone bill. She overspends badly. Why did the quizzes not prevent it?","choices":[{"id":"missing-vars","label":"The quizzes never had fatigue, peer pressure, or surprise bills in them — real life adds variables paper cannot show","feedback":"[Street-smart] Correct. Knowing the right answer in a calm moment and doing it on a tired Friday are different skills. The gap is normal; closing it is the real curriculum."},{"id":"didnt-study","label":"She did not really learn it — acing quizzes is meaningless","feedback":"[Street-smart] The knowledge was real; the conditions were different. Quizzes test recall. Real life tests recall PLUS exhaustion, emotions, and social pressure all at once."},{"id":"smart-enough","label":"She is just not smart enough with money","feedback":"[Street-smart] This is character talk, and it is wrong. Her system failed under load, not her intelligence. Smart people blow budgets too — that is why systems exist."},{"id":"predict","label":"No one could have predicted those events","feedback":"[Street-smart] Actually, ALL of those events are predictable in general: tired Fridays happen, friends push plans, surprise bills arrive. Plans should budget for the category \"life happens,\" not each specific event."}],"correct":"missing-vars"},{"verb":"decide","basis":"street","prompt":"Jordan set a budget, blew it by week two, and wants to throw the whole thing out. What is the move that actually works?","choices":[{"id":"adjust","label":"Keep the budget, shrink it to what survived, and fix the one leak he noticed — a budget that survives first contact beats a perfect one that shatters","feedback":"[Street-smart] Correct. The plan breaking is the lesson, not the failure. Noticing fast and adjusting the system is the entire skill — not executing a fantasy perfectly."},{"id":"trash","label":"Trash it — a budget that breaks in week two was a bad budget","feedback":"[Street-smart] Every first budget breaks. Throwing it out throws out the data too — the leak he noticed IS the curriculum. Revise, do not resign."},{"id":"stricter","label":"Make it stricter and punish himself for slipping","feedback":"[Street-smart] Stricter budgets break faster, and punishment teaches shame, not skill. He needs a sturdier system, not a harsher warden."},{"id":"perfect","label":"Start over with a perfect, detailed budget this time","feedback":"[Street-smart] A perfect budget that shatters on contact is worse than a rough one that survives. He does not need more detail; he needs a plan built for reality."}],"correct":"adjust"},{"verb":"compare","basis":"street","prompt":"Liam wants to learn investing. Option 1: put $500 into a stock his friend hyped. Option 2: put $5 into a practice setup and watch it for a month. Compare the learning.","choices":[{"id":"small","label":"Option 2 teaches the same lesson for 1% of the cost — small experiments, cheap lessons","feedback":"[Street-smart] Correct. Older generations learned by making $500 mistakes. Your job is to make $5 mistakes: simulations and small real amounts teach the pattern; the dollar amount only changes the tuition."},{"id":"real","label":"Option 1 — you only really learn when real money is at stake","feedback":"[Street-smart] You learn the same lesson either way — what $5 teaches you about risk, the $500 version teaches too, just with a $495 surcharge."},{"id":"friend","label":"Option 1 — his friend already did the research, so the risk is low","feedback":"[Street-smart] A friend's hype is not research, and \"low risk because a friend said so\" is how $500 lessons get made. Verify before trusting any tip."},{"id":"boring","label":"Option 2 — but only because investing is boring and slow","feedback":"[Street-smart] The right answer for the wrong reason. Option 2 wins because cheap experiments beat expensive ones — not because investing is boring. Boring is a feature, not a verdict."}],"correct":"small"},{"verb":"explain","basis":"street","prompt":"Maya impulse-buys shoes she does not need and feels guilty for two days. She calls herself \"bad with money.\" What is the useful read on that guilt?","choices":[{"id":"data","label":"The guilt is her system flagging a mismatch — log the trigger, learn it, adjust the system","feedback":"[Street-smart] Correct. Feelings are data. Guilt is not weakness; it is a dashboard light. Log what triggered the buy (tired? stressed? bored?), then change the system — unsubscribe, delete the app, add a waiting rule."},{"id":"weakness","label":"It proves she is weak and needs to try harder","feedback":"[Street-smart] Guilt-as-verdict teaches shame; shame teaches hiding, not skill. The same feeling read as data — \"what triggered this?\" — actually prevents the next one."},{"id":"ignore","label":"Ignore it — feelings have nothing to do with money","feedback":"[Street-smart] Feelings drive most spending. Ignoring the data guarantees the pattern repeats. The feeling IS the information."},{"id":"never","label":"Never buy anything fun again so the guilt stops","feedback":"[Street-smart] A plan with zero fun is a plan that explodes. The fix is a system for fun money, not a vow of joylessness that lasts a week."}],"correct":"data"},{"verb":"decide","basis":"street","prompt":"Jordan keeps saying \"I will save what is left at the end of the month.\" Every month, nothing is left. His motivation is real but the money still vanishes. What should he change?","choices":[{"id":"auto","label":"Pay himself first: an automatic transfer on payday into a separate account before he can spend it","feedback":"[Street-smart] Correct. \"Save what is left\" loses to a tired Friday every time. An automatic transfer works when motivation does not — the system saves; willpower gets to rest."},{"id":"try-harder","label":"Try harder next month — his motivation just needs to be stronger","feedback":"[Street-smart] His motivation was already real. Every \"just be disciplined\" plan fails eventually because motivation is a mood and bills are a schedule."},{"id":"earn-more","label":"Earn more money — the problem is the paycheck is too small","feedback":"[Street-smart] A bigger paycheck with the same system just means bigger vanishing. The leak is structural (no automatic save), not arithmetic."},{"id":"track","label":"Track every penny by hand — awareness alone will fix it","feedback":"[Street-smart] Tracking shows where money went; it does not stop it from going. Awareness without an automatic system is a report, not a fix."}],"correct":"auto"},{"verb":"predict","basis":"street","prompt":"Liam is $200 short on a bill and thinking \"I will figure it out, I do not want anyone to know.\" Predict where this goes if shame keeps him silent for six months.","choices":[{"id":"grows","label":"The $200 problem grows — late fees, interest, and stress compound while shame keeps him quiet","feedback":"[Street-smart] Correct. Shame is the most expensive fee there is. A $200 problem at month one is a $2,000 problem at month six. Counselors, nonprofits, and trusted adults exist for exactly this — early."},{"id":"solves","label":"It will probably work itself out — small problems fade","feedback":"[Street-smart] Money problems do not fade; they compound. Late fees and interest are automatic. Silence is the accelerant, not the solution."},{"id":"hide","label":"He should hide it better so no one finds out","feedback":"[Street-smart] Hiding is the shame talking. Every month of hiding adds fees and closes options. The help he is avoiding is cheapest right now."},{"id":"borrow","label":"He should borrow from a friend to cover it quietly","feedback":"[Street-smart] Quiet borrowing replaces one secret debt with another and risks the friendship too. A nonprofit credit counselor costs nothing and does not come with strings."}],"correct":"grows"},{"verb":"spot","basis":"street","prompt":"Maya notices she always overspends on Sundays: bored, phone in hand, shopping apps open. She decides the problem is that she is \"impulsive.\" What is the sharper diagnosis?","choices":[{"id":"system","label":"The problem is the setup — Sunday boredom + phone + shopping apps = a system that manufactures impulse buys. Change the setup.","feedback":"[Street-smart] Correct. She is not \"an impulsive person\"; she has an impulsivity machine in her pocket on Sundays. Delete the apps, plan a Sunday activity, add a 24-hour wait rule — adjust the system, not the character."},{"id":"character","label":"She is right — some people are just impulsive and she is one of them","feedback":"[Street-smart] Character labels are dead ends: they explain everything and fix nothing. The pattern has a time, a place, and a trigger — all changeable."},{"id":"delete-phone","label":"She should throw her phone away on weekends","feedback":"[Street-smart] Too extreme to survive — plans that require superhuman moves die in a week. Delete the SHOPPING apps, keep the phone. Bounded changes beat dramatic ones."},{"id":"sunday-ban","label":"She should never spend any money on Sundays","feedback":"[Street-smart] A Sunday spending ban treats the symptom with a rule she will break. Removing the trigger (the apps) and adding a wait rule works with her habits instead of against them."}],"correct":"system"},{"verb":"mc","basis":"street","prompt":"Jordan is finishing this whole course. If he could keep only ONE sentence from it, which one carries the most weight?","choices":[{"id":"gap","label":"\"Your plan will break on contact with reality — the skill is noticing fast and adjusting, not executing perfectly.\"","feedback":"[Street-smart] Correct. That sentence holds the whole capstone: knowing is not doing, feelings are data, systems beat willpower, and cheap mistakes beat expensive ones. It is the graduation line."},{"id":"memorize","label":"\"Memorize every definition so you never make a mistake.\"","feedback":"[Street-smart] Memorizing never survived a tired Friday. The course taught systems and adjustment — not perfect recall."},{"id":"rich","label":"\"Follow the steps and you will get rich.\"","feedback":"[Street-smart] No course can promise that, and this one never did. It promised something better: cheaper mistakes and faster recovery."},{"id":"perfect","label":"\"Never deviate from a budget once you make it.\"","feedback":"[Street-smart] The exact opposite of the lesson. A rigid budget shatters; a budget that survives first contact wins."}],"correct":"gap"},{"verb":"explain","basis":"street","prompt":"Liam impulse-buys a game he does not play and feels awful. What is the useful move?","choices":[{"id":"t0c0","label":"Treat the guilt as data: log the trigger, adjust the system (unsubscribe, wait rule)","feedback":"Yes — dashboard light, not character judgment. [Street-smart] Feelings are data. Log the trigger (tired? bored? ad?), then change the system so the trigger fires less often."},{"id":"t0c1","label":"Call himself bad with money and try harder","feedback":"Re-read: guilt is the system flagging a mismatch."},{"id":"t0c2","label":"Ignore the feeling — it has nothing to do with money","feedback":"Re-read: guilt is the system flagging a mismatch."},{"id":"t0c3","label":"Never buy games again","feedback":"Re-read: guilt is the system flagging a mismatch."}],"correct":"t0c0"},{"verb":"decide","basis":"street","prompt":"Jordan is $200 behind on a payment and embarrassed to tell anyone. Month one. What should he do?","choices":[{"id":"t1c0","label":"Tell a trusted adult or nonprofit counselor now — small problems are cheapest at the start","feedback":"Right — help is cheapest the day you ask. [Street-smart] Counselors, nonprofits, and trusted adults exist for exactly this moment. Early help is cheap; silence compounds like interest."},{"id":"t1c1","label":"Hide it until it gets serious enough to mention","feedback":"Shame is the most expensive fee. Month six turns $200 into $2,000."},{"id":"t1c2","label":"Borrow quietly from a friend","feedback":"Shame is the most expensive fee. Month six turns $200 into $2,000."},{"id":"t1c3","label":"Wait — it will probably work itself out","feedback":"Shame is the most expensive fee. Month six turns $200 into $2,000."}],"correct":"t1c0"}]};
for (const [k, v] of Object.entries(RWMS_PRACTICE))
  ADULT_PRACTICE_VARIANT_BANK[k] = [...(ADULT_PRACTICE_VARIANT_BANK[k] || []), ...v];

import { ADULT_WORKED_EXAMPLES } from './adult-life-variants-3.js';
const RWMS_WORKED = {"nd-money":[{"h":"Maya's Sunday check-in","story":"Maya has ADHD and her money kept vanishing. She never felt herself spending it — taps, saved cards, and subscriptions just drained her account, and every Friday the balance shocked her.She built one system: every Sunday after breakfast, five minutes. She opens her bank app, reads the transaction notifications she turned on, and writes the week's total on a whiteboard on her fridge. Her spending account stays low on purpose — when the whiteboard number climbs toward her limit, she SEES it. She deleted saved card numbers and unsubscribed from store emails. Two months in, no more surprise Fridays.","math":"The check-in rides on a routine she already does — no willpower, no remembering. Notifications + whiteboard make invisible digital money visible. Deleted saved cards and marketing emails remove the impulse triggers, not just the impulses. A low-balance spending account is a guardrail, not a punishment."}],"debt-warfare":[{"h":"The $15,000 car: 36 months vs 60 months","story":"Maya needs a car. She borrows $15,000 at 8%. The dealer offers two versions of the same loan: 36 months at about $470/month, or 60 months at about $304/month.The $304 payment feels easier — almost $170 less every month. Maya runs the totals instead of trusting the feeling. 36 months: about $1,900 in total interest. 60 months: about $3,250 in total interest. The “easier” payment costs roughly $1,350 extra, for the exact same car. (Example numbers, rounded — the shape is the lesson.)","math":"The monthly payment is not the price — total interest is the price. Interest accrues on the remaining balance every month, so a slower payoff keeps a bigger balance alive longer. If the longer term is the only way the payment fits, pay extra whenever you can — every extra dollar kills future interest."}],"student-loans":[{"h":"Maya funds college without the trap","story":"Maya gets into a school that costs $25,000 a year. Before borrowing a dollar, she works all three scholarship levels: she asks the financial-aid office and lands a $6,000 college scholarship; she applies to five local awards and wins two for $3,000 total; she tries two national ones and wins nothing. Gap left: $16,000.She takes the full $16,000 in federal loans and declines the private loan the bank offered — federal means income-driven plans and deferment if life goes sideways. After graduation she earns $40,000. On RAP, suppose her payment is set at 5% of her AGI — that is $2,000 a year, about $167 a month — and her balance cannot grow while she pays. Rules are changing through 2028, so she verifies the current options at StudentAid.gov before choosing. (The 5% figure is illustrative arithmetic within RAP's 1%–10% range, not her actual rate.)","math":"Scholarships first, all three levels: $6,000 college + $3,000 local = $9,000 she never repays. Federal before private: same $16,000 borrowed, but federal carries the safety nets. RAP shape: payment scales with income (illustrative $167/mo at $40,000 AGI), balance cannot grow while paying."}],"retirement":[{"h":"Jordan turns $100 a month into $380,000+","story":"Jordan starts her first job at 18. She opens a Roth IRA and auto-transfers $100 a month — money she barely misses. At an illustrative 7% average annual growth, here is the shape of it: by 28 she has put in $12,000 and the account holds roughly $17,000. By 38: $24,000 in, about $52,000 total. By 48: $36,000 in, about $122,000. By 58: $48,000 in, about $265,000. At 65: $56,400 in, about $380,000+ — all tax-free, because Roth.Now the cost of waiting: if she starts at 28 instead of 18, same $100 a month, same illustrative 7%, she lands around $210,000 — about $170,000 less, and every decade skipped pushes the gap into the hundreds of thousands. Actual returns vary, and 7% is an illustrative assumption, not a promise. She cannot open an account at 12 — but knowing this at 12 beats learning it at 32.","math":"Total put in from 18: $56,400. Total at 65: $380,000+. The gap is compounding, not contributions. Growth is back-loaded: the last decade adds more than the first three combined. Starting at 28 costs roughly $170,000 — time matters more than amount."}],"shopping-smart":[{"h":"The $12 case that \"saved\" $5","story":"Maya wants a $28 hoodie. Shipping is $5, but orders over $35 ship free. She adds a $12 phone case she barely wants to \"unlock\" free shipping. Her total: $40. If she had just paid the shipping, her total would have been $33. She did not save $5 — she spent $7 extra.The store designed that $35 threshold on purpose. It knows most people will add something to \"save\" the shipping fee, and the something they add almost always costs more than the fee.","math":"Always compare TOTALS: $28 + $5 shipping = $33 vs $28 + $12 case = $40. The threshold is a trap, not a gift — it is engineered to make you add items. If you genuinely wanted the extra item, fine. If you bought it for the shipping, you lost."}],"the-gap":[{"h":"Maya's first paycheck weekend","story":"Maya aced every quiz in this app. Then her first paycheck arrived on a tired Friday. Friends wanted dinner out. Her phone bill was higher than expected. By Sunday night, the budget she had planned so carefully was gone.Here is what she did next — the part that actually matters. She did not quit budgeting. She wrote down what broke it: Friday exhaustion, peer pressure, a surprise bill. Then she changed the SYSTEM: automatic savings on payday, a separate \"fun money\" account, and a rule to wait 24 hours before any unplanned purchase over $20. Month two was not perfect. It was better. That is the whole game.","math":"Knowing is not doing — real life adds fatigue, pressure, and surprises that paper never shows. The plan breaking is the lesson, not the failure. Noticing fast and adjusting is the skill. She changed the system (auto-transfer, separate account, wait rule), not her character."}]};
for (const [k, v] of Object.entries(RWMS_WORKED))
  ADULT_WORKED_EXAMPLES[k] = [...(ADULT_WORKED_EXAMPLES[k] || []), ...v];
